const { DataTypes } = require("sequelize");
const sequelize = require("../config/database");

/**
 * A settlement invoice: "for the period X-Y, School A's students paid us
 * a total of ₹Z; our platform commission on that is ₹C + GST; net payable
 * to School A is ₹Z - ₹C - GST." Generated by an admin from the Schools
 * tab, covers a specific date range, and is immutable once created (to
 * regenerate with different numbers, create a fresh invoice — don't edit
 * an issued one, same as you wouldn't edit a real tax invoice after the
 * fact).
 */
const SchoolInvoice = sequelize.define(
  "SchoolInvoice",
  {
    id: {
      type: DataTypes.UUID,
      defaultValue: DataTypes.UUIDV4,
      primaryKey: true,
    },
    schoolId: { type: DataTypes.UUID, allowNull: false },
    invoiceNumber: { type: DataTypes.STRING, allowNull: false, unique: true },

    // Null periodStart/periodEnd = "all payments not yet covered by a
    // previous invoice for this school", i.e. an open-ended/all-time
    // invoice. Otherwise both are set (inclusive range).
    periodStart: { type: DataTypes.DATE, allowNull: true },
    periodEnd: { type: DataTypes.DATE, allowNull: true },

    paymentCount: { type: DataTypes.INTEGER, defaultValue: 0 },
    totalCollected: { type: DataTypes.FLOAT, allowNull: false },

    commissionPercent: { type: DataTypes.FLOAT, allowNull: false },
    commissionAmount: { type: DataTypes.FLOAT, allowNull: false },
    gstPercent: { type: DataTypes.FLOAT, allowNull: false, defaultValue: 18 },
    gstAmount: { type: DataTypes.FLOAT, allowNull: false },
    netPayableToSchool: { type: DataTypes.FLOAT, allowNull: false },

    pdfFileName: { type: DataTypes.STRING, allowNull: false },
    generatedByAdminId: { type: DataTypes.UUID, allowNull: true },
  },
  {
    tableName: "school_invoices",
    timestamps: true,
  }
);

module.exports = SchoolInvoice;
